import {fetchSafeDocumentFragment} from '@github-ui/fetch-utils'
import {isEditMode} from './user-status'
import {observe} from '@github-ui/selector-observer'
import {remoteForm, type Kicker} from '@github-ui/remote-form'
import {announce} from '@github-ui/aria-live'

remoteForm('.js-user-status-form', async function (form, wants) {
  if (form.getAttribute('data-format') === 'html') {
    await updateUserStatusHtml(form, wants)
  } else {
    await broadcastUserStatusJson(form, wants)
  }
})

async function broadcastUserStatusJson(form: HTMLFormElement, wants: Kicker) {
  const formGroup = form.querySelector<HTMLElement>('.js-user-status-form-group')!
  formGroup.classList.remove('errored')

  let response
  try {
    response = await wants.json()
    showBanner(form)

    const dialog = form.matches('.js-user-status-dialog-form')
      ? (form.querySelector('modal-dialog, dialog') as HTMLDialogElement)
      : (form.closest('modal-dialog, dialog') as HTMLDialogElement)

    dialog.dispatchEvent(new CustomEvent('global-user-status-dialog:submit', {bubbles: true, detail: response.json}))
  } catch {
    formGroup.classList.add('errored')
    return
  }
}

async function updateUserStatusHtml(form: HTMLFormElement, wants: Kicker) {
  const formGroup = form.querySelector<HTMLElement>('.js-user-status-form-group')!
  formGroup.classList.remove('errored')

  let response
  try {
    response = await wants.html()
    showBanner(form)
  } catch {
    formGroup.classList.add('errored')
    return
  }

  const newContainer = response.html.querySelector('.js-user-status-container') as HTMLElement
  // Update the status containers on the page for non-drawer / side panel status updates.
  const otherContainers = document.querySelectorAll('.js-user-status-container')

  for (const otherContainer of otherContainers) {
    if (newContainer !== otherContainer) {
      const context = otherContainer.closest('.js-user-status-context')

      if (context) {
        const url = context.getAttribute('data-url')
        if (!url) throw new Error('could not get url')
        const fragment = await fetchSafeDocumentFragment(document, url)

        otherContainer.replaceWith(fragment)
      }
    }
  }
  const statusBannerMessage = document.querySelector<HTMLElement>('.js-user-status-banner-message')
  if (statusBannerMessage) {
    statusBannerMessage.setAttribute('tabindex', '-1')
    statusBannerMessage.focus()
  }
}

function toggleUserStatusEditHoverEffects(container: Element, show: boolean) {
  if (isEditMode(container)) {
    // Don't show mouseover effects if we're already in edit mode
    return
  }

  const elements = container.querySelectorAll('.js-toggle-user-status-edit.Details-content--closed')
  for (const el of elements) {
    el.classList.toggle('color-fg-accent', show)
    el.classList.toggle('Link--primary', !show)
  }
}

function showUserStatusEditHoverEffects(event: Event) {
  if (!(event.target instanceof Element)) return

  const container = event.target.closest<HTMLElement>('.js-user-status-container')!
  toggleUserStatusEditHoverEffects(container, true)
}

function hideUserStatusEditHoverEffects(event: Event) {
  if (!(event.target instanceof Element)) return

  const container = event.target.closest<HTMLElement>('.js-user-status-container')!
  toggleUserStatusEditHoverEffects(container, false)
}

function showBanner(form: HTMLFormElement) {
  const userStatusEmoji = form.querySelector<HTMLInputElement>('.js-user-status-emoji-field')?.value
  const userStatusMessage = form.querySelector<HTMLInputElement>('.js-user-status-message-field')?.value
  toggleBanner(userStatusEmoji, userStatusMessage)
}

function toggleBanner(userStatusEmoji?: string, userStatusMessage?: string) {
  const statusBanner = document.querySelector('.js-user-status-banner') as HTMLElement
  if (statusBanner) {
    const statusBannerMessage = statusBanner.querySelector<HTMLElement>('.js-user-status-banner-message')!
    let message: string
    if (userStatusEmoji || userStatusMessage) {
      // eslint-disable-next-line i18n-text/no-en
      message = 'Your status has been updated.'
    } else {
      // eslint-disable-next-line i18n-text/no-en
      message = 'Your status has been cleared.'
    }
    statusBannerMessage.textContent = message
    statusBanner.hidden = false
    announce(message)
  }
}

observe('.js-toggle-user-status-edit', function (el) {
  el.addEventListener('mouseenter', showUserStatusEditHoverEffects)
  el.addEventListener('mouseleave', hideUserStatusEditHoverEffects)
})

// Handles the 'react-user-status-dialog:submit' event dispatched by the React UserStatusDialog component.
// The event is a CustomEvent with a 'detail' object of the form: { emojiAttributes?: string; message?: string }
observe('.js-user-status-container', function (container) {
  container.addEventListener('react-user-status-dialog:submit', async response => {
    try {
      // Update the status containers on the page for non-drawer / side panel status updates.
      const otherContainers = document.querySelectorAll('.js-user-status-container')

      for (const otherContainer of otherContainers) {
        const context = otherContainer.closest('.js-user-status-context')

        if (context) {
          const url = context.getAttribute('data-url')
          if (!url) throw new Error('Failed to get data-url attribute from user status context element')
          const fragment = await fetchSafeDocumentFragment(document, url)

          otherContainer.replaceWith(fragment)
        }
      }
    } catch (error) {
      // eslint-disable-next-line no-console
      console.error('Failed to reload page:', error)
      return
    }

    const {detail} = response as CustomEvent<{emojiAttributes?: string; message?: string}>

    toggleBanner(detail.emojiAttributes, detail.message)
  })
})
